"""FuzzExecutor frame conversion and execution against an injected transport."""
from typing import Any, Dict, List

from HTTP3_Just_Send import HttpClient
from modules.byte_program import EMPTY, concat, fingerprint, leaf, size
from modules.clock import Clock
from modules.events import (ConnectionTerminated, DataReceived, HeadersReceived,
                            SendError)


def encoded_action(at, stream, kind, data, end=False):
    """Exact receipt encoding of one emitted or accepted action."""
    head = leaf(at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode('ascii'))
    if kind in ('H', 'h'):
        pairs = list(data)
        content = leaf(len(pairs).to_bytes(8, 'big'))
        for name, value in pairs:
            content = concat(content, leaf(size(name).to_bytes(8, 'big')))
            content = concat(content, name)
            content = concat(content, leaf(size(value).to_bytes(8, 'big')))
            content = concat(content, value)
    else:
        content = concat(leaf(size(data).to_bytes(8, 'big')), data)
    return concat(concat(head, content), leaf(bytes((1 if end else 0,))))


class CaseAccount:
    """Per case emission and reception bookkeeping."""

    __slots__ = ('sent', 'received', 'body', 'frames', 'request_frames',
                 'payload_bytes', 'response_frames')

    def __init__(self):
        self.sent = EMPTY
        self.received = EMPTY
        self.body = EMPTY
        self.frames = 0
        self.request_frames = 0
        self.payload_bytes = 0
        self.response_frames = 0


class OfflineTransport:
    """Injected decoded-event backend recording exact client receipts."""

    def __init__(self, clock, count):
        self.clock = clock
        self.next_stream = 0
        self.ended = set()
        self.accounts = [CaseAccount() for _ in range(count)]
        self.client = None

    def get_next_available_stream_id(self):
        stream = self.next_stream
        self.next_stream += 4
        return stream

    def request_ended(self, stream_id):
        return stream_id in self.ended

    def record(self, stream_id, kind, data, end_stream=False):
        if stream_id in self.ended:
            raise SendError('frame after request end')
        index = stream_id // 4
        account = self.accounts[index]
        account.sent = concat(account.sent,
                              encoded_action(self.clock.now, stream_id, kind,
                                             data, end_stream))
        account.frames += 1
        if kind in ('H', 'D'):
            account.request_frames += 1
        if kind == 'H':
            account.payload_bytes += sum(size(name) + size(value)
                                         for name, value in data)
        else:
            account.payload_bytes += size(data)
        if end_stream:
            self.ended.add(stream_id)

    def send_headers(self, stream_id, headers, end_stream):
        self.record(stream_id, 'H', headers, end_stream)

    def send_data(self, stream_id, data, end_stream):
        self.record(stream_id, 'D', data, end_stream)

    def send_datagram(self, stream_id, data):
        self.record(stream_id, 'G', data, False)

    def dispatch(self, record):
        kind = record['kind']
        if kind == 'close':
            self.client.quic_event_received(ConnectionTerminated())
        elif kind == 'headers':
            self.client.quic_event_received(
                HeadersReceived(record['stream'], record['fields'], record['end']))
        else:
            self.client.quic_event_received(
                DataReceived(record['stream'], record['data'], record['end']))


class FuzzExecutor:
    """Drives compiled payloads through the offline client and transport."""

    def __init__(self, target_ip=None, target_port=None, domain=None):
        self.target_ip = target_ip
        self.target_port = target_port
        self.domain = domain

    def _convert_single_case_frames(self, frames: List[Any]) -> List[Dict[str, Any]]:
        converted_frames = []
        for item in frames:
            kind = item.Type
            if kind == 'headers':
                converted_frames.append({
                    'Type': 'headers',
                    'data_to_transfered': [list(pair) for pair in item.data_to_transfered],
                    'End_Stream': bool(item.End_Stream),
                })
            elif kind in ('data', 'datagram'):
                converted_frames.append({
                    'Type': kind,
                    'data_to_transfered': item.data_to_transfered,
                    'End_Stream': bool(item.End_Stream),
                })
            else:
                converted_frames.append({
                    'Type': 'sleep',
                    'Time_to_Stop': item.Time_to_Stop,
                })
        return converted_frames

    def send_payload(self, payload, records, timeout_ms):
        clock = Clock()
        entries = list(payload.test_cases.items())
        transport = OfflineTransport(clock, len(entries))
        client = HttpClient(clock, transport, timeout_ms)
        transport.client = client
        coroutines = [client.request(self._convert_single_case_frames(frames), index)
                      for index, (_, frames) in enumerate(entries)]
        results = clock.run(coroutines, records, transport.dispatch)
        out = []
        for index, result in enumerate(results):
            account = transport.accounts[index]
            stream = result['stream']
            for at, event in result['events']:
                if isinstance(event, HeadersReceived):
                    action = encoded_action(at, stream, 'h', event.headers,
                                            event.stream_ended)
                else:
                    action = encoded_action(at, stream, 'd', event.data,
                                            event.stream_ended)
                    account.body = concat(account.body, event.data)
                account.received = concat(account.received, action)
                account.response_frames += 1
            out.append({
                'name': entries[index][0],
                'stream': stream,
                'state': result['state'],
                'at': result['at'],
                'frames': account.frames,
                'request_frames': account.request_frames,
                'payload_bytes': account.payload_bytes,
                'sent': fingerprint(account.sent),
                'received': fingerprint(account.received),
                'response_frames': account.response_frames,
                'response_body': fingerprint(account.body),
                'origin_count': 0,
                'flags': [],
            })
        return out
